-- +goose Up

-- The failure dictionary: rules that turn a raw code from a carrier, a vendor
-- or our own gate into a plain explanation. Resolved at read time, so an edit
-- changes every past message it matches on the next read. Platform-wide, not
-- per tenant: a carrier's code means the same thing to every customer.
--
-- A rule answers one question: (channel, source, route, vendor, match). Two
-- rules answering the same question would make resolution depend on row order,
-- so the unique index refuses the second.
CREATE TABLE failure_reasons (
    id               text        PRIMARY KEY,
    channel          text        CHECK (channel IN ('SMS', 'RCS', 'WHATSAPP', 'EMAIL', 'VOICE')),
    source           text        NOT NULL CHECK (source IN ('gate', 'smpp_submit', 'smpp_receipt',
                                     'rcs_vendor', 'whatsapp', 'email', 'voice')),
    route_id         text,
    vendor           text,
    match_kind       text        NOT NULL CHECK (match_kind IN ('exact', 'prefix')),
    match_value      text        NOT NULL CHECK (length(match_value) > 0),
    layer            text        NOT NULL CHECK (layer IN ('ours', 'regulator', 'sender_setup',
                                     'carrier', 'handset', 'provider')),
    code             text        NOT NULL CHECK (length(code) > 0),
    title            text        NOT NULL CHECK (length(title) > 0),
    detail           text,
    fix              text,
    fix_kind         text        CHECK (fix_kind IN ('compliance', 'senders', 'templates', 'wallet',
                                     'audience', 'suppressions', 'limits', 'support')),
    retryable        boolean     NOT NULL DEFAULT false,
    auto_retried     boolean     NOT NULL DEFAULT false,
    customer_visible boolean     NOT NULL DEFAULT true,
    version          integer     NOT NULL DEFAULT 1 CHECK (version >= 1),
    updated_by       text,
    updated_at       timestamptz
);
CREATE UNIQUE INDEX failure_reasons_question ON failure_reasons (
    coalesce(channel, ''), source, coalesce(route_id, ''), coalesce(vendor, ''),
    match_kind, match_value);

-- Rules an operator adds are numbered from here, clear of every seeded id.
CREATE SEQUENCE failure_reason_ids START 1000;

GRANT SELECT, INSERT, UPDATE ON failure_reasons TO sms_app;
GRANT USAGE ON SEQUENCE failure_reason_ids TO sms_app;

